@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldSaveOrderWhenCreated() {
        var order = new Order(1L, "Laptop", 1200.00);

        orderService.createOrder(order);

        verify(orderRepository).save(order);  // asserts save() was called once with this order
    }

    @Test
    void shouldNotifyCustomerAfterOrderSaved() {
        var order = new Order(2L, "Phone", 800.00);

        orderService.createOrder(order);

        verify(orderRepository).save(any(Order.class));  // called with any Order
        verify(notificationService).sendEmail(order.getCustomerId());  // email was sent
    }
}
