@ExtendWith(MockitoExtension.class)
class UserServiceTest {
    @Mock
    private UserRepository userRepository;
    @InjectMocks
    private UserService userService;
    @Captor
    private ArgumentCaptor<User> userCaptor;  // declare captor for User type

    @Test
    void shouldCreateUserWithCorrectFields() {
        var request = new CreateUserRequest("john.doe", "john@example.com");

        userService.createUser(request);  // internally creates new User and calls save()

        verify(userRepository).save(userCaptor.capture());  // capture the argument
        var savedUser = userCaptor.getValue();  // extract the captured User

        assertThat(savedUser.getUsername()).isEqualTo("john.doe");
        assertThat(savedUser.getEmail()).isEqualTo("john@example.com");
        assertThat(savedUser.getCreatedAt()).isNotNull();  // verify timestamp was set
    }
}
