@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private PaymentGateway paymentGateway;
    @Mock
    private EmailService emailService;
    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldNotChargePaymentWhenOrderIsInvalid() {
        var invalidOrder = new Order(null, "Laptop", -100.00);  // negative price

        var result = orderService.createOrder(invalidOrder);

        assertThat(result.isSuccess()).isFalse();
        verify(paymentGateway, never()).charge(any());  // charge() should not have been called
    }

    @Test
    void shouldNotSendNotificationInDryRunMode() {
        var order = new Order(5L, "Phone", 800.00);

        orderService.createOrderDryRun(order);  // dry run mode

        verifyNoInteractions(emailService);  // no methods on emailService should have been called
    }
}
